import { create } from "zustand";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";
import {
  type AgentInfo,
  type AgentStatus,
  type AgentStatusEvent,
  sendMessage as sendMessageCmd,
  sendFollowupMessage as sendFollowupCmd,
  stopAgent as stopAgentCmd,
  getAgentStatus,
} from "../lib/tauri";
import { pushStreamEvent } from "../lib/ipcInstrumentation";

interface AgentStore {
  agents: Record<string, AgentInfo>;
  subscriptions: Record<string, UnlistenFn>;
  needsAttention: Record<string, boolean>;
  runStartedAt: Record<string, number>;

  getStatus: (workspaceId: string) => AgentStatus;
  subscribe: (workspaceId: string) => Promise<void>;
  unsubscribe: (workspaceId: string) => void;
  clearNeedsAttention: (workspaceId: string) => void;
  sendMessage: (
    contextId: string,
    message: string,
    contextType?: "workspace" | "repo",
    model?: string,
    disableThinking?: boolean,
    disablePlanMode?: boolean,
  ) => Promise<void>;
  broadcastMessage: (
    workspaceIds: string[],
    message: string,
    model?: string,
  ) => Promise<{ succeeded: string[]; failed: { workspaceId: string; error: string }[] }>;
  stopAgent: (workspaceId: string) => Promise<void>;
  stopAllAgents: (workspaceIds: string[]) => Promise<void>;
  fetchStatus: (workspaceId: string) => Promise<void>;
}

export const useAgentStore = create<AgentStore>((set, get) => ({
  agents: {},
  subscriptions: {},
  needsAttention: {},
  runStartedAt: {},

  getStatus: (workspaceId: string): AgentStatus => {
    return get().agents[workspaceId]?.status ?? "Idle";
  },

  subscribe: async (workspaceId: string) => {
    // Don't double-subscribe
    if (get().subscriptions[workspaceId]) return;

    const unlisten = await listen<AgentStatusEvent>(
      `agent-status:${workspaceId}`,
      (event) => {
        const newStatus = event.payload.status;
        const prevStatus = get().agents[workspaceId]?.status ?? "Idle";
        pushStreamEvent(workspaceId, "status_changed", `${JSON.stringify(prevStatus)} -> ${JSON.stringify(newStatus)}`);
        const becameIdle = prevStatus === "Running" && newStatus === "Idle";
        const becameRunning = prevStatus !== "Running" && newStatus === "Running";
        set((state) => {
          const runStartedAt = { ...state.runStartedAt };
          if (becameRunning) {
            runStartedAt[workspaceId] = Date.now();
          } else if (becameIdle) {
            delete runStartedAt[workspaceId];
          }
          return {
            agents: {
              ...state.agents,
              [workspaceId]: {
                ...state.agents[workspaceId],
                workspaceId,
                status: newStatus,
              } as AgentInfo,
            },
            runStartedAt,
            ...(becameIdle
              ? { needsAttention: { ...state.needsAttention, [workspaceId]: true } }
              : {}),
          };
        });
      },
    );

    set((state) => ({
      subscriptions: { ...state.subscriptions, [workspaceId]: unlisten },
    }));
  },

  unsubscribe: (workspaceId: string) => {
    const unsub = get().subscriptions[workspaceId];
    if (unsub) {
      unsub();
      set((state) => {
        const { [workspaceId]: _, ...rest } = state.subscriptions;
        return { subscriptions: rest };
      });
    }
  },

  clearNeedsAttention: (workspaceId: string) => {
    set((state) => ({
      needsAttention: { ...state.needsAttention, [workspaceId]: false },
    }));
  },

  sendMessage: async (
    contextId: string,
    message: string,
    contextType: "workspace" | "repo" = "workspace",
    model?: string,
    disableThinking?: boolean,
    disablePlanMode?: boolean,
  ) => {
    try {
      // If agent is already running, send as a follow-up via stdin
      const status = get().agents[contextId]?.status;
      if (status === "Running") {
        await sendFollowupCmd(contextId, message);
        return;
      }

      const request =
        contextType === "workspace"
          ? { workspaceId: contextId, message, model: model || undefined, disableThinking, disablePlanMode }
          : { repoId: contextId, message, model: model || undefined, disableThinking, disablePlanMode };
      await sendMessageCmd(request);
    } catch (e) {
      console.error(`[agentStore] Failed to send message:`, e);
      throw e;
    }
  },

  broadcastMessage: async (
    workspaceIds: string[],
    message: string,
    model?: string,
  ) => {
    const succeeded: string[] = [];
    const failed: { workspaceId: string; error: string }[] = [];
    const results = await Promise.allSettled(
      workspaceIds.map((id) =>
        sendMessageCmd({ workspaceId: id, message, model: model || undefined }),
      ),
    );
    results.forEach((result, i) => {
      if (result.status === "fulfilled") {
        succeeded.push(workspaceIds[i]);
      } else {
        failed.push({ workspaceId: workspaceIds[i], error: String(result.reason) });
      }
    });
    return { succeeded, failed };
  },

  stopAgent: async (workspaceId: string) => {
    try {
      await stopAgentCmd(workspaceId);
    } catch (e) {
      console.error(`[agentStore] Failed to stop agent:`, e);
      throw e;
    }
  },

  stopAllAgents: async (workspaceIds: string[]) => {
    await Promise.allSettled(workspaceIds.map((id) => stopAgentCmd(id)));
  },

  fetchStatus: async (workspaceId: string) => {
    try {
      const info = await getAgentStatus(workspaceId);
      set((state) => ({
        agents: { ...state.agents, [workspaceId]: info },
      }));
    } catch (e) {
      console.error(`[agentStore] Failed to fetch status:`, e);
    }
  },
}));

