      id: "ws1:a.ts",
      filePath: "a.ts",
      contextType: "workspace",
      contextId: "ws1",
      content: "original",
      editedContent: "edited",
      dirty: true,
    });
    const tab2 = makeTab({
      id: "ws1:b.ts",
      filePath: "b.ts",
      content: "other",
    });
    useFileViewerStore.setState({ tabs: [tab1, tab2], activeTabId: tab1.id });
    await useFileViewerStore.getState().saveActiveFile();

