    });
    useFileViewerStore.setState({ tabs: [tab], activeTabId: tab.id });
    await useFileViewerStore.getState().saveActiveFile(false);

    expect(writeWorkspaceFile).toHaveBeenCalledWith(
      "ws1",
      "app.ts",
      "edited",
      false,
    );
  });
});

