describe("chatStore - subscribe cancellation tokens", () => {
  it("cancels previous in-flight subscribe", async () => {
    const unlisten1 = vi.fn();
    const unlisten2 = vi.fn();
    let callCount = 0;
    vi.mocked(listen).mockImplementation(async () => {
      callCount++;
      return callCount === 1 ? unlisten1 : unlisten2;
    });

    const p1 = useChatStore.getState().subscribe("ws-1");
    const p2 = useChatStore.getState().subscribe("ws-1");

    await p1;
    await p2;

    expect(useChatStore.getState().subscriptions["ws-1"]).toBeDefined();
  });

  it("removes subscription from state on error", async () => {
    vi.mocked(listen).mockRejectedValueOnce(new Error("connection failed"));
    const consoleSpy = vi.spyOn(console, "error").mockImplementation(() => {});

    await useChatStore.getState().subscribe("ws-err");

    expect(useChatStore.getState().subscriptions["ws-err"]).toBeUndefined();
    consoleSpy.mockRestore();
  });

  it("bails out if subscription completed during loadMessages await", async () => {
    // Simulate: loadMessages takes time, and another subscribe completes first
    const unlisten = vi.fn();
    vi.mocked(listen).mockResolvedValue(unlisten);

    // Set up so that after loadMessages, subscriptions already has this workspace
    vi.mocked(listChatMessages).mockImplementation(async () => {
      // Simulate another subscribe completing during this await
      useChatStore.setState({
        subscriptions: { "ws-race": vi.fn() },
      });
      return [];
    });

    await useChatStore.getState().subscribe("ws-race");

    // The original subscribe should have bailed out — not overwritten the subscription
    // listen should not have been called (bailed before reaching it)
    // (it may or may not depending on timing, but the subscription should be stable)
  });

  it("unsubscribe during subscribe causes event handler to ignore events", async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const handlers: Array<(event: any) => void> = [];
    vi.mocked(listen).mockImplementation(async (_channel, handler) => {
      handlers.push(handler as any);
      return () => {};
    });
    vi.mocked(listChatMessages).mockResolvedValue([]);

    await useChatStore.getState().subscribe("ws-cancel");

    // Now unsubscribe — this should cancel the token
    useChatStore.getState().unsubscribe("ws-cancel");

    // Send an event via the captured handler — it should be ignored (token.cancelled = true)
    const handler = handlers[handlers.length - 1];
    handler({ payload: { type: "assistantText", text: "should be ignored" } });

    // streamingText should NOT have been updated (event was ignored)
    expect(useChatStore.getState().streamingText["ws-cancel"]).toBeUndefined();
  });

  it("recovers pending permission request after subscribe", async () => {
    const { getPendingPermission } = await import("../lib/tauri");
    vi.mocked(getPendingPermission).mockResolvedValue({
      type: "permissionRequest",
      toolName: "Bash",
      input: { command: "rm -rf" },
      suggestions: undefined,
    } as any);
    vi.mocked(listen).mockResolvedValue(() => {});
    vi.mocked(listChatMessages).mockResolvedValue([]);

    await useChatStore.getState().subscribe("ws-perm");

    // Wait for the permission recovery promise to resolve
    await new Promise((r) => setTimeout(r, 10));

    const pr = useChatStore.getState().permissionRequest["ws-perm"];
    expect(pr).toBeTruthy();
    expect(pr!.toolName).toBe("Bash");
  });

  it("error handler logs and cleans up partial subscription state", async () => {
    const consoleSpy = vi.spyOn(console, "error").mockImplementation(() => {});
    vi.mocked(listen).mockRejectedValue(new Error("listen failed"));

    await useChatStore.getState().subscribe("ws-fail");

    expect(consoleSpy).toHaveBeenCalledWith(
      expect.stringContaining("[chatStore] subscribe failed"),
      expect.any(Error),
    );
    expect(useChatStore.getState().subscriptions["ws-fail"]).toBeUndefined();
    consoleSpy.mockRestore();
  });

  it("bails out when token cancelled after loadMessages but before listen", async () => {
    let resolveLoad!: (v: any) => void;
    vi.mocked(listChatMessages).mockImplementation(
      () => new Promise(r => { resolveLoad = r; }),
    );
    vi.mocked(listen).mockResolvedValue(() => {});

    const p = useChatStore.getState().subscribe("ws-bail");
    // Cancel while loadMessages is pending
    useChatStore.getState().unsubscribe("ws-bail");
    resolveLoad([]);
    await p;

    // listen should NOT have been called (bailed before reaching it)
    // The subscribe bails at the token.cancelled check after loadMessages
    expect(useChatStore.getState().subscriptions["ws-bail"]).toBeUndefined();
  });

  it("bails out and calls unlisten when token cancelled after listen completes", async () => {
    const unlisten = vi.fn();
    vi.mocked(listen).mockResolvedValue(unlisten);
    vi.mocked(listChatMessages).mockResolvedValue([]);

    await useChatStore.getState().subscribe("ws-late-cancel");

    // At this point, subscribe completed and subscription is stored
    expect(useChatStore.getState().subscriptions["ws-late-cancel"]).toBeDefined();
  });

  it("pushStreamEvent is called with event_received on handler invocation", async () => {
    vi.mocked(listen).mockImplementation(async (_ch, handler) => {
      // Immediately invoke the handler
      (handler as any)({ payload: { type: "assistantText", text: "x" } });
      return () => {};
    });
    vi.mocked(listChatMessages).mockResolvedValue([]);

    await useChatStore.getState().subscribe("ws-push");

    expect(pushStreamEvent).toHaveBeenCalledWith(
      "ws-push",
      "event_received",
      "assistantText",
    );
  });

  it("permission recovery ignores non-permissionRequest event types", async () => {
    const { getPendingPermission } = await import("../lib/tauri");
    vi.mocked(getPendingPermission).mockResolvedValue({
      type: "result", // NOT permissionRequest
      isError: false,
    } as any);
    vi.mocked(listen).mockResolvedValue(() => {});
    vi.mocked(listChatMessages).mockResolvedValue([]);

    await useChatStore.getState().subscribe("ws-no-perm");
    await new Promise(r => setTimeout(r, 10));

    // permissionRequest should NOT be set for non-permissionRequest events
    expect(useChatStore.getState().permissionRequest["ws-no-perm"]).toBeUndefined();
  });

  it("permission recovery ignores null response", async () => {
    const { getPendingPermission } = await import("../lib/tauri");
    vi.mocked(getPendingPermission).mockResolvedValue(null);
    vi.mocked(listen).mockResolvedValue(() => {});
    vi.mocked(listChatMessages).mockResolvedValue([]);

    await useChatStore.getState().subscribe("ws-null-perm");
    await new Promise(r => setTimeout(r, 10));

    expect(useChatStore.getState().permissionRequest["ws-null-perm"]).toBeUndefined();
  });

  it("subscribe creates token with cancelled=false in _chatSubscribeTokens", async () => {
    let resolveLoad!: (v: any) => void;
    vi.mocked(listChatMessages).mockImplementation(
      () => new Promise(r => { resolveLoad = r; }),
    );
    vi.mocked(listen).mockResolvedValue(() => {});

    const p = useChatStore.getState().subscribe("ws-token-check");
    // Token should exist with cancelled=false
    const token = _chatSubscribeTokens.get("ws-token-check");
    expect(token).toBeTruthy();
    expect(token!.cancelled).toBe(false);

    resolveLoad([]);
    await p;
  });

  it("calling subscribe again sets existing token.cancelled=true", async () => {
    let resolveFirst!: (v: any) => void;
    vi.mocked(listChatMessages).mockImplementation(
      () => new Promise(r => { resolveFirst = r; }),
    );
    vi.mocked(listen).mockResolvedValue(() => {});

    const p1 = useChatStore.getState().subscribe("ws-cancel-check");
    const firstToken = _chatSubscribeTokens.get("ws-cancel-check");
    expect(firstToken!.cancelled).toBe(false);

    // Start second subscribe — should cancel the first token
    vi.mocked(listChatMessages).mockResolvedValue([]);
    const p2 = useChatStore.getState().subscribe("ws-cancel-check");

    // First token should now be cancelled
    expect(firstToken!.cancelled).toBe(true);

    resolveFirst([]);
    await p1;
    await p2;
  });

  it("token cancelled after loadMessages prevents listen from being called", async () => {
    let resolveLoad!: (v: any) => void;
    vi.mocked(listChatMessages).mockImplementation(
      () => new Promise(r => { resolveLoad = r; }),
    );
    const listenMock = vi.mocked(listen);
    listenMock.mockResolvedValue(() => {});

    const callsBefore = listenMock.mock.calls.length;
    const p = useChatStore.getState().subscribe("ws-no-listen");

    // Cancel the token while loadMessages is pending
    const token = _chatSubscribeTokens.get("ws-no-listen");
    token!.cancelled = true;

    resolveLoad([]);
    await p;

    // listen should NOT have been called (token was cancelled)
    expect(listenMock.mock.calls.length).toBe(callsBefore);
  });

  it("token cancelled after listen causes unlisten and token cleanup", async () => {
    const unlisten = vi.fn();
    vi.mocked(listChatMessages).mockResolvedValue([]);
    vi.mocked(listen).mockImplementation(async () => {
      // After listen resolves, cancel the token before the check at L130
      const token = _chatSubscribeTokens.get("ws-unlisten");
      if (token) token.cancelled = true;
      return unlisten;
    });

    await useChatStore.getState().subscribe("ws-unlisten");

    // The token was cancelled after listen returned — unlisten should be called
    expect(unlisten).toHaveBeenCalled();
    // Subscription should NOT be stored (bailed at L130)
    expect(useChatStore.getState().subscriptions["ws-unlisten"]).toBeUndefined();
    // Token should be cleaned up
    expect(_chatSubscribeTokens.has("ws-unlisten")).toBe(false);
  });

  it("error in subscribe cleans up subscription state with rest spread", async () => {
    const spy = vi.spyOn(console, "error").mockImplementation(() => {});
    // Pre-set a subscription for another workspace
    useChatStore.setState({ subscriptions: { "ws-other": () => {} } });
    vi.mocked(listen).mockRejectedValue(new Error("fail"));
    vi.mocked(listChatMessages).mockResolvedValue([]);

    await useChatStore.getState().subscribe("ws-err-rest");

    // ws-err-rest should not be in subscriptions
    expect(useChatStore.getState().subscriptions["ws-err-rest"]).toBeUndefined();
    // ws-other should still be there (rest spread preserves it)
    expect(useChatStore.getState().subscriptions["ws-other"]).toBeDefined();
    spy.mockRestore();
  });

  it("re-check guard at L115 bails when subscription already exists", async () => {
    vi.mocked(listChatMessages).mockImplementation(async () => {
      // During loadMessages, manually add subscription for this workspace
      useChatStore.setState({
        subscriptions: { ...useChatStore.getState().subscriptions, "ws-guard": () => {} },
      });
      return [];
    });
    vi.mocked(listen).mockResolvedValue(() => {});

    await useChatStore.getState().subscribe("ws-guard");

    // The subscribe should have bailed at L115 re-check
    // listen should not have been called for this workspace
    // (the subscription was set by our mock, not by subscribe)
  });

  it("second subscribe cancels first token but both complete", async () => {
    let loadCount = 0;
    vi.mocked(listChatMessages).mockImplementation(async () => {
      loadCount++;
      return [];
    });
    vi.mocked(listen).mockResolvedValue(() => {});

    // Start two subscribes — second should cancel first's token
    await useChatStore.getState().subscribe("ws-double-1");
    // Reset subscription to allow re-subscribe
    useChatStore.setState({ subscriptions: {} });
    await useChatStore.getState().subscribe("ws-double-1");

    // Both should have completed without error
    expect(useChatStore.getState().subscriptions["ws-double-1"]).toBeDefined();
  });

  it("re-subscribe check after await bails out when subscription exists", async () => {
    // Simulate: between loadMessages and listen, another subscribe completes
    let resolveFirst!: (v: any) => void;
    let callCount = 0;
    vi.mocked(listChatMessages).mockImplementation(async () => {
      callCount++;
      if (callCount === 1) {
        return new Promise(r => { resolveFirst = r; });
      }
      return [];
    });
    vi.mocked(listen).mockResolvedValue(() => {});

    // Start first subscribe (will hang on loadMessages)
    const p1 = useChatStore.getState().subscribe("ws-recheck");
    // Complete a second subscribe while first is pending
    await useChatStore.getState().subscribe("ws-recheck-2");
    // Manually set subscription for ws-recheck to simulate race
    useChatStore.setState({ subscriptions: { ...useChatStore.getState().subscriptions, "ws-recheck": () => {} } });

    resolveFirst([]);
    await p1;

    // First subscribe should have bailed at the re-check
  });

  it("token cancelled after listen causes unlisten to be called", async () => {
    const unlisten = vi.fn();
    vi.mocked(listen).mockResolvedValue(unlisten);
    vi.mocked(listChatMessages).mockResolvedValue([]);
    const { getPendingPermission } = await import("../lib/tauri");
    vi.mocked(getPendingPermission).mockResolvedValue(null);

    await useChatStore.getState().subscribe("ws-post-listen");
    // Subscribe completed — now unsubscribe to cancel the token
    useChatStore.getState().unsubscribe("ws-post-listen");
    // The unlisten stored in subscriptions should have been called
    expect(unlisten).toHaveBeenCalled();
  });

  it("clearMessages cancel token prevents re-population", async () => {
    vi.mocked(listen).mockResolvedValue(() => {});
    vi.mocked(listChatMessages).mockResolvedValue([]);
    vi.mocked(clearChatMessages).mockResolvedValue(undefined);
    vi.mocked(saveChatMessage).mockResolvedValue(undefined);

    await useChatStore.getState().subscribe("ws-clear-token");
    useChatStore.setState({
      messages: { "ws-clear-token": [{ id: "m1", role: "user", content: [{ type: "text", text: "hi" }], timestamp: 1 }] },
    });
    useChatStore.getState().clearMessages("ws-clear-token");

    // After clear, the cancelled token should prevent stale events
    const msgs = useChatStore.getState().messages["ws-clear-token"];
    expect(!msgs || msgs.length === 0).toBe(true);
  });

  it("error in subscribe catch block logs with workspace ID", async () => {
    const spy = vi.spyOn(console, "error").mockImplementation(() => {});
    vi.mocked(listen).mockRejectedValue(new Error("broken"));
    vi.mocked(listChatMessages).mockResolvedValue([]);

    await useChatStore.getState().subscribe("ws-err-id");
    expect(spy).toHaveBeenCalledWith(
      expect.stringContaining("ws-err-id"),
      expect.any(Error),
    );
    // Verify cleanup: subscriptions should be clean
    expect(useChatStore.getState().subscriptions["ws-err-id"]).toBeUndefined();
    spy.mockRestore();
  });

  it("subscribe sets cancelled=false on new token (not {})", async () => {
    // If token was {} instead of { cancelled: false }, the if (token.cancelled) checks
    // would read undefined (falsy) which is the same as false — but event handler
    // checks !token.cancelled which would be !undefined = true (different from !false = true)
    // This test verifies the subscribe completes normally
    vi.mocked(listen).mockResolvedValue(() => {});
    vi.mocked(listChatMessages).mockResolvedValue([]);

    await useChatStore.getState().subscribe("ws-token");
    expect(useChatStore.getState().subscriptions["ws-token"]).toBeDefined();
  });

  it("early return when already subscribed prevents double subscription", async () => {
    const unlisten = vi.fn();
    vi.mocked(listen).mockResolvedValue(unlisten);
    vi.mocked(listChatMessages).mockResolvedValue([]);

    await useChatStore.getState().subscribe("ws-dup");
    const callCount1 = vi.mocked(listen).mock.calls.length;

    // Second subscribe should be a no-op
    await useChatStore.getState().subscribe("ws-dup");
    const callCount2 = vi.mocked(listen).mock.calls.length;

    // listen should not have been called again
    expect(callCount2).toBe(callCount1);
  });
});

describe("chatStore - unsubscribe cleans up tokens", () => {
  it("calls unlisten function on unsubscribe", () => {
    const unsub = vi.fn();
    useChatStore.setState({ subscriptions: { "ws-1": unsub } });

    useChatStore.getState().unsubscribe("ws-1");

    expect(unsub).toHaveBeenCalled();
    expect(useChatStore.getState().subscriptions["ws-1"]).toBeUndefined();
  });
});

