    await useAgentStore.getState().sendMessage("repo-1", "hi", "repo", "haiku");
    expect(sendMessageCmd).toHaveBeenCalledWith(
      expect.objectContaining({ repoId: "repo-1", model: "haiku" }),
    );
  });
});

