  // --- countLines with empty text ---

  it("shows Read label without line count when result is null", () => {
    render(
      <MessageBubble
        message={makeMessage({
          role: "assistant",
          content: [
            { type: "toolUse", id: "t1", name: "Read", input: { file_path: "/a.ts" } },
          ],
        })}
      />,
    );
    expect(screen.getByText("Read")).toBeInTheDocument();
  });
});

