import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen } from "@testing-library/react";
import { CommandPalette } from "./CommandPalette";
import { useWorkspaceStore } from "../stores/workspaceStore";
import { useRepositoryStore } from "../stores/repositoryStore";
import { useUIStore } from "../stores/uiStore";
import { SHORTCUTS } from "../lib/keybindings";

vi.mock("cmdk", () => ({
  Command: ({ children, ...props }: any) => <div data-testid="command" {...props}>{children}</div>,
  CommandDialog: ({ children, open }: any) => open ? <div data-testid="command-dialog">{children}</div> : null,
  CommandEmpty: ({ children }: any) => <div>{children}</div>,
  CommandGroup: ({ children, heading }: any) => <div data-testid={`group-${heading}`}>{children}</div>,
  CommandInput: (props: any) => <input {...props} data-testid="command-input" />,
  CommandItem: ({ children, onSelect, keywords, ...props }: any) => (
    <div onClick={onSelect} role="option" data-keywords={keywords?.join(",")} {...props}>{children}</div>
  ),
  CommandList: ({ children }: any) => <div>{children}</div>,
  CommandSeparator: () => <hr />,
}));

beforeEach(() => {
  useWorkspaceStore.setState({
    workspaces: [],
    activeWorkspaceId: null,
  });
  useRepositoryStore.setState({
    repositories: [],
  });
  useUIStore.setState({
    rightSidebarTab: "files",
  });
  vi.clearAllMocks();
});

describe("CommandPalette", () => {
  it("does not render when closed", () => {
    render(
      <CommandPalette open={false} onOpenChange={vi.fn()} onAction={vi.fn()} />,
    );
    expect(screen.queryByTestId("command-dialog")).not.toBeInTheDocument();
  });

  it("renders when open", () => {
    render(
      <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} />,
    );
    expect(screen.getByTestId("command-dialog")).toBeInTheDocument();
  });

  it("renders sidebar section with expected items", () => {
    render(
      <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} />,
    );
    expect(screen.getByText("All Files")).toBeInTheDocument();
    expect(screen.getByText("Changes")).toBeInTheDocument();
    expect(screen.getByText("Checks / PR")).toBeInTheDocument();
    expect(screen.getByText("Toggle Right Sidebar")).toBeInTheDocument();
  });

  it("renders views section", () => {
    render(
      <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} />,
    );
    expect(screen.getByText("Switch to Chat")).toBeInTheDocument();
    expect(screen.getByText("Open Settings")).toBeInTheDocument();
    expect(screen.getByText("Open Merge View")).toBeInTheDocument();
    expect(screen.getByText("Open History")).toBeInTheDocument();
  });

  it("renders actions section", () => {
    render(
      <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} />,
    );
    expect(screen.getByText("Focus Terminal")).toBeInTheDocument();
    expect(screen.getByText("New Workspace")).toBeInTheDocument();
    expect(screen.getByText("New Session")).toBeInTheDocument();
  });

  // --- Individual command selections ---
  describe("command selections", () => {
    it("calls onAction with right-sidebar-files on All Files click", () => {
      const onAction = vi.fn();
      const onOpenChange = vi.fn();
      render(
        <CommandPalette open={true} onOpenChange={onOpenChange} onAction={onAction} />,
      );
      screen.getByText("All Files").click();
      expect(onAction).toHaveBeenCalledWith("right-sidebar-files");
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });

    it("calls onAction with right-sidebar-changes on Changes click", () => {
      const onAction = vi.fn();
      const onOpenChange = vi.fn();
      render(
        <CommandPalette open={true} onOpenChange={onOpenChange} onAction={onAction} />,
      );
      screen.getByText("Changes").click();
      expect(onAction).toHaveBeenCalledWith("right-sidebar-changes");
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });

    it("calls onAction with right-sidebar-checks on Checks / PR click", () => {
      const onAction = vi.fn();
      const onOpenChange = vi.fn();
      render(
        <CommandPalette open={true} onOpenChange={onOpenChange} onAction={onAction} />,
      );
      screen.getByText("Checks / PR").click();
      expect(onAction).toHaveBeenCalledWith("right-sidebar-checks");
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });

    it("calls onAction with toggle-right-sidebar", () => {
      const onAction = vi.fn();
      const onOpenChange = vi.fn();
      render(
        <CommandPalette open={true} onOpenChange={onOpenChange} onAction={onAction} />,
      );
      screen.getByText("Toggle Right Sidebar").click();
      expect(onAction).toHaveBeenCalledWith("toggle-right-sidebar");
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });

    it("calls onAction with view-chat on Switch to Chat click", () => {
      const onAction = vi.fn();
      const onOpenChange = vi.fn();
      render(
        <CommandPalette open={true} onOpenChange={onOpenChange} onAction={onAction} />,
      );
      screen.getByText("Switch to Chat").click();
      expect(onAction).toHaveBeenCalledWith("view-chat");
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });

    it("calls onAction with open-settings on Open Settings click", () => {
      const onAction = vi.fn();
      const onOpenChange = vi.fn();
      render(
        <CommandPalette open={true} onOpenChange={onOpenChange} onAction={onAction} />,
      );
      screen.getByText("Open Settings").click();
      expect(onAction).toHaveBeenCalledWith("open-settings");
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });

    it("calls onAction with view-merge on Open Merge View click", () => {
      const onAction = vi.fn();
      const onOpenChange = vi.fn();
      render(
        <CommandPalette open={true} onOpenChange={onOpenChange} onAction={onAction} />,
      );
      screen.getByText("Open Merge View").click();
      expect(onAction).toHaveBeenCalledWith("view-merge");
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });

    it("calls onAction with view-history on Open History click", () => {
      const onAction = vi.fn();
      const onOpenChange = vi.fn();
      render(
        <CommandPalette open={true} onOpenChange={onOpenChange} onAction={onAction} />,
      );
      screen.getByText("Open History").click();
      expect(onAction).toHaveBeenCalledWith("view-history");
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });

    it("calls onAction with focus-terminal on Focus Terminal click", () => {
      const onAction = vi.fn();
      const onOpenChange = vi.fn();
      render(
        <CommandPalette open={true} onOpenChange={onOpenChange} onAction={onAction} />,
      );
      screen.getByText("Focus Terminal").click();
      expect(onAction).toHaveBeenCalledWith("focus-terminal");
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });

    it("calls onAction with new-workspace on New Workspace click", () => {
      const onAction = vi.fn();
      const onOpenChange = vi.fn();
      render(
        <CommandPalette open={true} onOpenChange={onOpenChange} onAction={onAction} />,
      );
      screen.getByText("New Workspace").click();
      expect(onAction).toHaveBeenCalledWith("new-workspace");
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });

    it("calls onAction with new-session on New Session click", () => {
      const onAction = vi.fn();
      const onOpenChange = vi.fn();
      render(
        <CommandPalette open={true} onOpenChange={onOpenChange} onAction={onAction} />,
      );
      screen.getByText("New Session").click();
      expect(onAction).toHaveBeenCalledWith("new-session");
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });

    it("calls onAction with toggle-notifications", () => {
      const onAction = vi.fn();
      const onOpenChange = vi.fn();
      render(
        <CommandPalette open={true} onOpenChange={onOpenChange} onAction={onAction} />,
      );
      screen.getByText("Toggle Notifications").click();
      expect(onAction).toHaveBeenCalledWith("toggle-notifications");
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });

    it("calls onAction with view-team", () => {
      const onAction = vi.fn();
      const onOpenChange = vi.fn();
      render(
        <CommandPalette open={true} onOpenChange={onOpenChange} onAction={onAction} />,
      );
      screen.getByText("Open Team View").click();
      expect(onAction).toHaveBeenCalledWith("view-team");
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });

    it("calls onAction with view-usage", () => {
      const onAction = vi.fn();
      const onOpenChange = vi.fn();
      render(
        <CommandPalette open={true} onOpenChange={onOpenChange} onAction={onAction} />,
      );
      screen.getByText("Open Usage Dashboard").click();
      expect(onAction).toHaveBeenCalledWith("view-usage");
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });

    it("calls onAction with toggle-split-editor", () => {
      const onAction = vi.fn();
      const onOpenChange = vi.fn();
      render(
        <CommandPalette open={true} onOpenChange={onOpenChange} onAction={onAction} />,
      );
      screen.getByText("Toggle Split Editor").click();
      expect(onAction).toHaveBeenCalledWith("toggle-split-editor");
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });

    it("calls onAction with open-snippets", () => {
      const onAction = vi.fn();
      const onOpenChange = vi.fn();
      render(
        <CommandPalette open={true} onOpenChange={onOpenChange} onAction={onAction} />,
      );
      screen.getByText("Open Snippet Manager").click();
      expect(onAction).toHaveBeenCalledWith("open-snippets");
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });

    it("calls onAction with export-workspace", () => {
      const onAction = vi.fn();
      const onOpenChange = vi.fn();
      render(
        <CommandPalette open={true} onOpenChange={onOpenChange} onAction={onAction} />,
      );
      screen.getByText("Export Workspace").click();
      expect(onAction).toHaveBeenCalledWith("export-workspace");
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });
  });

  // --- Workspace switching ---
  describe("workspace switching", () => {
    it("shows workspace switching section when multiple workspaces exist", () => {
      useWorkspaceStore.setState({
        workspaces: [
          { id: "ws-1", name: "Workspace 1", repoId: "r1", branch: "main" },
          { id: "ws-2", name: "Workspace 2", repoId: "r1", branch: "dev" },
        ] as any,
        activeWorkspaceId: "ws-1",
      });
      useRepositoryStore.setState({
        repositories: [{ id: "r1", name: "my-repo" }] as any,
      });
      render(
        <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} />,
      );
      // Should show non-active workspace for switching
      expect(screen.getByText("Workspace 2")).toBeInTheDocument();
    });

    it("does not show workspace switching with only one workspace", () => {
      useWorkspaceStore.setState({
        workspaces: [{ id: "ws-1", name: "Only WS", repoId: "r1", branch: "main" }] as any,
        activeWorkspaceId: "ws-1",
      });
      render(
        <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} />,
      );
      expect(screen.queryByTestId("group-Switch Workspace")).not.toBeInTheDocument();
    });

    it("clicking workspace switch calls setActive on workspace store", () => {
      const onOpenChange = vi.fn();
      const setActiveSpy = vi.fn();
      useWorkspaceStore.setState({
        workspaces: [
          { id: "ws-1", name: "Workspace 1", repoId: "r1", branch: "main" },
          { id: "ws-2", name: "Workspace 2", repoId: "r1", branch: "dev" },
          { id: "ws-3", name: "Workspace 3", repoId: "r1", branch: "feat" },
        ] as any,
        activeWorkspaceId: "ws-1",
        setActive: setActiveSpy,
      });
      useRepositoryStore.setState({
        repositories: [{ id: "r1", name: "my-repo" }] as any,
      });
      render(
        <CommandPalette open={true} onOpenChange={onOpenChange} onAction={vi.fn()} />,
      );
      screen.getByText("Workspace 2").click();
      expect(onOpenChange).toHaveBeenCalledWith(false);
      expect(setActiveSpy).toHaveBeenCalledWith("ws-2");
    });

    it("shows repo name and branch for workspace switch items", () => {
      useWorkspaceStore.setState({
        workspaces: [
          { id: "ws-1", name: "WS 1", repoId: "r1", branch: "main" },
          { id: "ws-2", name: "WS 2", repoId: "r1", branch: "dev" },
        ] as any,
        activeWorkspaceId: "ws-1",
      });
      useRepositoryStore.setState({
        repositories: [{ id: "r1", name: "my-repo" }] as any,
      });
      render(
        <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} />,
      );
      expect(screen.getByText(/my-repo \/ dev/)).toBeInTheDocument();
    });

    it("filters out active workspace from switch list", () => {
      useWorkspaceStore.setState({
        workspaces: [
          { id: "ws-1", name: "Active WS", repoId: "r1", branch: "main" },
          { id: "ws-2", name: "Other WS", repoId: "r1", branch: "dev" },
        ] as any,
        activeWorkspaceId: "ws-1",
      });
      useRepositoryStore.setState({
        repositories: [{ id: "r1", name: "my-repo" }] as any,
      });
      render(
        <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} />,
      );
      expect(screen.queryByText("Active WS")).not.toBeInTheDocument();
      expect(screen.getByText("Other WS")).toBeInTheDocument();
    });
  });

  // --- PaletteItem ---
  describe("PaletteItem", () => {
    it("shows active indicator for files tab when rightSidebarTab is files", () => {
      useUIStore.setState({ rightSidebarTab: "files" });
      render(
        <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} />,
      );
      // The All Files item should have data-active="true"
      const allFilesOption = screen.getByText("All Files").closest("[role='option']");
      expect(allFilesOption).toHaveAttribute("data-active", "true");
    });

    it("shows active indicator for changes tab when rightSidebarTab is changes", () => {
      useUIStore.setState({ rightSidebarTab: "changes" });
      render(
        <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} />,
      );
      const changesOption = screen.getByText("Changes").closest("[role='option']");
      expect(changesOption).toHaveAttribute("data-active", "true");
    });

    it("shows active indicator for checks tab when rightSidebarTab is checks", () => {
      useUIStore.setState({ rightSidebarTab: "checks" });
      render(
        <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} />,
      );
      const checksOption = screen.getByText("Checks / PR").closest("[role='option']");
      expect(checksOption).toHaveAttribute("data-active", "true");
    });

    it("shows keyboard shortcut for items that have shortcuts", () => {
      render(
        <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} />,
      );
      // The shortcutFor function should resolve shortcuts for known actions
      // Open Settings has a shortcut (Cmd+,)
      const kbds = document.querySelectorAll("kbd");
      expect(kbds.length).toBeGreaterThan(0);
    });

    it("does not show shortcut for items without shortcuts", () => {
      render(
        <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} />,
      );
      // view-chat does not have a shortcut in the SHORTCUTS array
      const chatItem = screen.getByText("Switch to Chat").closest("[role='option']");
      const kbd = chatItem?.querySelector("kbd");
      expect(kbd).toBeNull();
    });
  });

  // --- shortcutFor returns undefined for unknown actions ---
  it("returns undefined shortcut for unknown action", () => {
    render(
      <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} />,
    );
    // "New Session" doesn't have a shortcut; should not render kbd
    const newSessionItem = screen.getByText("New Session").closest("[role='option']");
    const kbd = newSessionItem?.querySelector("kbd");
    expect(kbd).toBeNull();
  });

  it("renders items without shortcuts (view-chat, view-merge, view-history, new-session) without kbd", () => {
    render(
      <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} />,
    );
    // These actions have no entry in the SHORTCUTS array, so shortcutFor returns undefined
    const noShortcutItems = ["Switch to Chat", "Open Merge View", "Open History", "New Session"];
    for (const label of noShortcutItems) {
      const item = screen.getByText(label).closest("[role='option']");
      expect(item?.querySelector("kbd")).toBeNull();
    }
  });

  // --- Workspace search mode ---
  describe("workspace-search mode", () => {
    beforeEach(() => {
      useWorkspaceStore.setState({
        workspaces: [
          { id: "ws-1", name: "Frontend App", repoId: "r1", branch: "main", status: "Active" },
          { id: "ws-2", name: "Backend API", repoId: "r2", branch: "feature/auth", status: "Active" },
        ] as any,
        archivedWorkspaces: [
          { id: "ws-3", name: "Old Project", repoId: "r1", branch: "legacy", status: "Archived" },
        ] as any,
        activeWorkspaceId: "ws-1",
      });
      useRepositoryStore.setState({
        repositories: [
          { id: "r1", name: "my-repo" },
          { id: "r2", name: "api-repo" },
        ] as any,
      });
    });

    it("hides non-workspace groups in workspace-search mode", () => {
      render(
        <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} mode="workspace-search" />,
      );
      expect(screen.queryByTestId("group-Sidebar")).not.toBeInTheDocument();
      expect(screen.queryByTestId("group-Views")).not.toBeInTheDocument();
      expect(screen.queryByTestId("group-Actions")).not.toBeInTheDocument();
      expect(screen.getByTestId("group-Workspaces")).toBeInTheDocument();
    });

    it("shows all workspaces including the active one", () => {
      render(
        <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} mode="workspace-search" />,
      );
      expect(screen.getByText("Frontend App")).toBeInTheDocument();
      expect(screen.getByText("Backend API")).toBeInTheDocument();
    });

    it("marks the active workspace with an active indicator", () => {
      render(
        <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} mode="workspace-search" />,
      );
      const activeItem = screen.getByText("Frontend App").closest("[role='option']");
      expect(activeItem).toHaveAttribute("data-active", "true");
    });

    it("shows archived workspaces with Archived badge", () => {
      render(
        <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} mode="workspace-search" />,
      );
      expect(screen.getByText("Old Project")).toBeInTheDocument();
      expect(screen.getByText("Archived")).toBeInTheDocument();
    });

    it("uses search workspaces placeholder", () => {
      render(
        <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} mode="workspace-search" />,
      );
      expect(screen.getByTestId("command-input")).toHaveAttribute("placeholder", "Search workspaces...");
    });

    it("includes repo name and branch as keywords for search", () => {
      render(
        <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} mode="workspace-search" />,
      );
      const backendItem = screen.getByText("Backend API").closest("[role='option']");
      expect(backendItem).toHaveAttribute("data-keywords", "api-repo,feature/auth");
    });

    it("clicking an active workspace calls setActive and closes palette", () => {
      const onOpenChange = vi.fn();
      const setActiveSpy = vi.fn();
      useWorkspaceStore.setState({
        ...useWorkspaceStore.getState(),
        setActive: setActiveSpy,
      });
      render(
        <CommandPalette open={true} onOpenChange={onOpenChange} onAction={vi.fn()} mode="workspace-search" />,
      );
      screen.getByText("Frontend App").click();
      expect(setActiveSpy).toHaveBeenCalledWith("ws-1");
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });

    it("clicking an archived workspace calls restoreWs then setActive", async () => {
      const onOpenChange = vi.fn();
      const setActiveSpy = vi.fn();
      const restoreWsSpy = vi.fn().mockResolvedValue(undefined);
      useWorkspaceStore.setState({
        ...useWorkspaceStore.getState(),
        setActive: setActiveSpy,
        restoreWs: restoreWsSpy,
      });
      render(
        <CommandPalette open={true} onOpenChange={onOpenChange} onAction={vi.fn()} mode="workspace-search" />,
      );
      screen.getByText("Old Project").click();
      expect(onOpenChange).toHaveBeenCalledWith(false);
      expect(restoreWsSpy).toHaveBeenCalledWith("ws-3");
      // setActive is called after restore resolves
      await vi.waitFor(() => {
        expect(setActiveSpy).toHaveBeenCalledWith("ws-3");
      });
    });

    it("does not mark non-active workspaces as active", () => {
      render(
        <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} mode="workspace-search" />,
      );
      const inactiveItem = screen.getByText("Backend API").closest("[role='option']");
      expect(inactiveItem).not.toHaveAttribute("data-active", "true");
    });

    it("shows Workspaces group even with a single workspace", () => {
      useWorkspaceStore.setState({
        workspaces: [
          { id: "ws-1", name: "Only WS", repoId: "r1", branch: "main", status: "Active" },
        ] as any,
        archivedWorkspaces: [] as any,
        activeWorkspaceId: "ws-1",
      });
      render(
        <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} mode="workspace-search" />,
      );
      expect(screen.getByTestId("group-Workspaces")).toBeInTheDocument();
      expect(screen.getByText("Only WS")).toBeInTheDocument();
    });

    it("shows fallback repo name when repository is not found", () => {
      useWorkspaceStore.setState({
        workspaces: [
          { id: "ws-99", name: "Orphan WS", repoId: "missing-repo", branch: "main", status: "Active" },
        ] as any,
        archivedWorkspaces: [] as any,
        activeWorkspaceId: "ws-99",
      });
      render(
        <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} mode="workspace-search" />,
      );
      expect(screen.getByText(/Unknown repo \/ main/)).toBeInTheDocument();
    });
  });

  it("shortcutFor returns undefined when SHORTCUTS has no matching action", async () => {
    // Temporarily clear SHORTCUTS array to exercise the undefined branch of shortcutFor
    const origShortcuts = [...SHORTCUTS];
    SHORTCUTS.length = 0;

    render(
      <CommandPalette open={true} onOpenChange={vi.fn()} onAction={vi.fn()} />,
    );

    // All items should render without any kbd shortcut labels
    const allOptions = screen.getAllByRole("option");
    for (const option of allOptions) {
      expect(option.querySelector("kbd")).toBeNull();
    }

    // Restore SHORTCUTS
    SHORTCUTS.push(...origShortcuts);
  });
});

src/components/settings/tabs/ProviderTab.source:
import { describe, it, expect, vi } from "vitest";
import { render, screen, fireEvent, waitFor, act } from "@testing-library/react";
import "./test-helpers";
import { fullSettings } from "./test-helpers";
import { AppSettingsPanel } from "../AppSettingsPanel";
import { useSettingsStore } from "../../../stores/settingsStore";
import { useUIStore } from "../../../stores/uiStore";

describe("ProviderTab", () => {
  const goToProviderTab = () => {
    render(<AppSettingsPanel />);
    fireEvent.click(screen.getByText("Provider"));
  };

  it("shows Loading when settings not yet loaded", async () => {
    useSettingsStore.setState({
      appSettings: null,
      loadSettings: vi.fn().mockResolvedValue(undefined),
    });
    render(<AppSettingsPanel />);
    fireEvent.click(screen.getByText("Provider"));
    expect(screen.getByText("Loading...")).toBeInTheDocument();
  });

  it("renders provider selector with all provider options", async () => {
    goToProviderTab();
    const select = await screen.findByDisplayValue("Anthropic");
    expect(select).toBeInTheDocument();
    expect(screen.getByText("OpenRouter")).toBeInTheDocument();
    expect(screen.getByText("Vercel AI Gateway")).toBeInTheDocument();
    expect(screen.getByText("AWS Bedrock")).toBeInTheDocument();
    expect(screen.getByText("Google Vertex")).toBeInTheDocument();
    expect(screen.getByText("Azure Foundry")).toBeInTheDocument();
    expect(screen.getByText("Custom")).toBeInTheDocument();
  });

  it("changes provider type when selector changes", async () => {
    goToProviderTab();
    const select = await screen.findByDisplayValue("Anthropic");
    fireEvent.change(select, { target: { value: "OpenRouter" } });
    await waitFor(() => {
      expect(screen.getByDisplayValue("OpenRouter")).toBeInTheDocument();
    });
  });

  it("shows ANTHROPIC_API_KEY hint input for Anthropic provider", async () => {
    goToProviderTab();
    await waitFor(() => {
      expect(screen.getByText("ANTHROPIC_API_KEY")).toBeInTheDocument();
    });
    expect(screen.getByPlaceholderText("Enter ANTHROPIC_API_KEY")).toBeInTheDocument();
  });

  it("shows Bedrock env var hints when Bedrock is selected", async () => {
    useSettingsStore.setState({
      appSettings: {
        ...fullSettings,
        provider: { providerType: "Bedrock", envVars: {} },
      },
    });
    render(<AppSettingsPanel />);
    fireEvent.click(screen.getByText("Provider"));
    await waitFor(() => {
      expect(screen.getByText("AWS_ACCESS_KEY_ID")).toBeInTheDocument();
      expect(screen.getByText("AWS_SECRET_ACCESS_KEY")).toBeInTheDocument();
      expect(screen.getByText("AWS_REGION")).toBeInTheDocument();
    });
  });

  it("does not show hint inputs for Custom provider", async () => {
    useSettingsStore.setState({
      appSettings: {
        ...fullSettings,
        provider: { providerType: "Custom", envVars: {} },
      },
    });
    render(<AppSettingsPanel />);
    fireEvent.click(screen.getByText("Provider"));
    await waitFor(() => {
      expect(screen.getByText("Additional Environment Variables")).toBeInTheDocument();
    });
    expect(screen.queryByText("Configuration")).not.toBeInTheDocument();
  });

  it("toggles env var visibility with Show/Hide button", async () => {
    goToProviderTab();
    await waitFor(() => {
      expect(screen.getByText("ANTHROPIC_API_KEY")).toBeInTheDocument();
    });
    const input = screen.getByPlaceholderText("Enter ANTHROPIC_API_KEY");
    expect(input).toHaveAttribute("type", "password");

    fireEvent.click(screen.getByText("Show"));
    expect(input).toHaveAttribute("type", "text");

    fireEvent.click(screen.getByText("Hide"));
    expect(input).toHaveAttribute("type", "password");
  });

  it("updates env var value when typing", async () => {
    goToProviderTab();
    await waitFor(() => {
      expect(
        screen.getByPlaceholderText("Enter ANTHROPIC_API_KEY"),
      ).toBeInTheDocument();
    });
    const input = screen.getByPlaceholderText("Enter ANTHROPIC_API_KEY");
    fireEvent.change(input, { target: { value: "sk-test-123" } });
    expect(input).toHaveValue("sk-test-123");
  });

  it("shows extra env vars that are not in hints", async () => {
    useSettingsStore.setState({
      appSettings: {
        ...fullSettings,
        provider: {
          providerType: "Anthropic",
          envVars: {
            ANTHROPIC_API_KEY: "sk-test",
            CUSTOM_VAR: "custom-value",
          },
        },
      },
    });
    render(<AppSettingsPanel />);
    fireEvent.click(screen.getByText("Provider"));
    await waitFor(() => {
      expect(screen.getByText("CUSTOM_VAR")).toBeInTheDocument();
      expect(screen.getByText("custom-value")).toBeInTheDocument();
    });
  });

  it("removes extra env var when X button is clicked", async () => {
    useSettingsStore.setState({
      appSettings: {
        ...fullSettings,
        provider: {
          providerType: "Anthropic",
          envVars: {
            ANTHROPIC_API_KEY: "sk-test",
            CUSTOM_VAR: "custom-value",
          },
        },
      },
    });
    render(<AppSettingsPanel />);
    fireEvent.click(screen.getByText("Provider"));
    await waitFor(() => {
      expect(screen.getByText("CUSTOM_VAR")).toBeInTheDocument();
    });
    const customVarRow = screen.getByText("CUSTOM_VAR").closest("div");
    const removeBtn = customVarRow!.querySelector("button");
    fireEvent.click(removeBtn!);
    await waitFor(() => {
      expect(screen.queryByText("CUSTOM_VAR")).not.toBeInTheDocument();
    });
  });

  it("adds a new env var using AddEnvVarRow", async () => {
    goToProviderTab();
    await waitFor(() => {
      expect(screen.getByPlaceholderText("KEY")).toBeInTheDocument();
    });
    const keyInput = screen.getByPlaceholderText("KEY");
    const valueInput = screen.getByPlaceholderText("value");
    fireEvent.change(keyInput, { target: { value: "MY_VAR" } });
    fireEvent.change(valueInput, { target: { value: "my_value" } });
    fireEvent.click(screen.getByText("Add"));
    await waitFor(() => {
      expect(screen.getByText("MY_VAR")).toBeInTheDocument();
    });
  });

  it("does not add env var when key is empty", async () => {
    goToProviderTab();
    await waitFor(() => {
      expect(screen.getByPlaceholderText("KEY")).toBeInTheDocument();
    });
    const valueInput = screen.getByPlaceholderText("value");
    fireEvent.change(valueInput, { target: { value: "my_value" } });
    fireEvent.click(screen.getByText("Add"));
    expect(screen.queryByText("my_value")).not.toBeInTheDocument();
  });

  it("adds env var via Enter key on value input", async () => {
    goToProviderTab();
    await waitFor(() => {
      expect(screen.getByPlaceholderText("KEY")).toBeInTheDocument();
    });
    const keyInput = screen.getByPlaceholderText("KEY");
    const valueInput = screen.getByPlaceholderText("value");
    fireEvent.change(keyInput, { target: { value: "ENTER_VAR" } });
    fireEvent.change(valueInput, { target: { value: "enter_value" } });
    fireEvent.keyDown(valueInput, { key: "Enter" });
    await waitFor(() => {
      expect(screen.getByText("ENTER_VAR")).toBeInTheDocument();
    });
  });

  it("does not add env var on non-Enter key press", async () => {
    goToProviderTab();
    await waitFor(() => {
      expect(screen.getByPlaceholderText("KEY")).toBeInTheDocument();
    });
    const keyInput = screen.getByPlaceholderText("KEY");
    const valueInput = screen.getByPlaceholderText("value");
    fireEvent.change(keyInput, { target: { value: "NOPE_VAR" } });
    fireEvent.change(valueInput, { target: { value: "nope_value" } });
    fireEvent.keyDown(valueInput, { key: "a" });
    expect(screen.queryByText("NOPE_VAR")).not.toBeInTheDocument();
  });

  it("saves settings and closes when Save is clicked", async () => {
    const saveSettings = vi.fn().mockResolvedValue(undefined);
    const closeViewTab = vi.fn();
    useSettingsStore.setState({ appSettings: fullSettings, saveSettings });
    useUIStore.setState({ closeViewTab });
    render(<AppSettingsPanel />);
    fireEvent.click(screen.getByText("Provider"));
    await waitFor(() => {
      expect(screen.getByText("Save")).toBeInTheDocument();
    });
    fireEvent.click(screen.getByText("Save"));
    await waitFor(() => {
      expect(saveSettings).toHaveBeenCalled();
      expect(closeViewTab).toHaveBeenCalledWith("settings");
    });
  });

  it("shows Saving... while save is in progress", async () => {
    let resolverFn: () => void;
    const savePromise = new Promise<void>((resolve) => {
      resolverFn = resolve;
    });
    const saveSettings = vi.fn().mockReturnValue(savePromise);
    useSettingsStore.setState({ appSettings: fullSettings, saveSettings });
    render(<AppSettingsPanel />);
    fireEvent.click(screen.getByText("Provider"));
    await waitFor(() => {
      expect(screen.getByText("Save")).toBeInTheDocument();
    });
    fireEvent.click(screen.getByText("Save"));
    await waitFor(() => {
      expect(screen.getByText("Saving...")).toBeInTheDocument();
    });
    await act(async () => {
      resolverFn!();
    });
  });

  it("shows error when save fails", async () => {
    const saveSettings = vi
      .fn()
      .mockRejectedValue(new Error("Network error"));
    useSettingsStore.setState({ appSettings: fullSettings, saveSettings });
    render(<AppSettingsPanel />);
    fireEvent.click(screen.getByText("Provider"));
    await waitFor(() => {
      expect(screen.getByText("Save")).toBeInTheDocument();
    });
    fireEvent.click(screen.getByText("Save"));
    await waitFor(() => {
      expect(screen.getByText("Error: Network error")).toBeInTheDocument();
    });
  });

  it("Cancel button closes settings", async () => {
    const closeViewTab = vi.fn();
    useUIStore.setState({ closeViewTab });
    goToProviderTab();
    await waitFor(() => {
      expect(screen.getByText("Cancel")).toBeInTheDocument();
    });
    fireEvent.click(screen.getByText("Cancel"));
    expect(closeViewTab).toHaveBeenCalledWith("settings");
  });

  it("changes provider type via select onChange", async () => {
    goToProviderTab();
    const select = await screen.findByDisplayValue("Anthropic");
    fireEvent.change(select, { target: { value: "Vertex" } });
    await waitFor(() => {
      expect(screen.getByText("GOOGLE_APPLICATION_CREDENTIALS")).toBeInTheDocument();
      expect(screen.getByText("GOOGLE_PROJECT_ID")).toBeInTheDocument();
    });
  });

  it("changes agent type when Agent select changes", async () => {
    goToProviderTab();
    const agentSelect = await screen.findByDisplayValue("Claude Code");
    fireEvent.change(agentSelect, { target: { value: "codex_cli" } });
    await waitFor(() => {
      expect(screen.getByDisplayValue("Codex CLI")).toBeInTheDocument();
    });
  });

  it("changes OPENAI_API_KEY value when typing", async () => {
    useSettingsStore.setState({
      appSettings: {
        ...fullSettings,
        agentType: "codex_cli" as const,
        provider: { providerType: "Anthropic" as const, envVars: {} },
      },
    });
    render(<AppSettingsPanel />);
    fireEvent.click(screen.getByText("Provider"));
    await waitFor(() => {
      expect(screen.getByPlaceholderText("Enter OPENAI_API_KEY")).toBeInTheDocument();
    });
    const input = screen.getByPlaceholderText("Enter OPENAI_API_KEY");
    fireEvent.change(input, { target: { value: "sk-test-key" } });
    expect(input).toHaveValue("sk-test-key");
  });

  it("toggles OPENAI_API_KEY visibility for Codex CLI agent", async () => {
    useSettingsStore.setState({
      appSettings: {
        ...fullSettings,
        agentType: "codex_cli" as const,
        provider: { providerType: "Anthropic" as const, envVars: {} },
      },
    });
    render(<AppSettingsPanel />);
    fireEvent.click(screen.getByText("Provider"));
    await waitFor(() => {
      expect(screen.getByText("OPENAI_API_KEY")).toBeInTheDocument();
    });
    const input = screen.getByPlaceholderText("Enter OPENAI_API_KEY");
    expect(input).toHaveAttribute("type", "password");
    const showButtons = screen.getAllByText("Show");
    fireEvent.click(showButtons[0]);
    expect(input).toHaveAttribute("type", "text");
    expect(screen.getByText("Hide")).toBeInTheDocument();
  });
});

