import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen, fireEvent } from "@testing-library/react";

vi.mock("@monaco-editor/react", () => ({
  DiffEditor: ({ original, modified }: any) => (
    <div data-testid="diff-editor">
      {original} → {modified}
    </div>
  ),
}));

vi.mock("../../lib/monacoTheme", () => ({
  MONACO_THEME: "test-theme",
  configureMonacoTheme: vi.fn(),
}));

vi.mock("../../lib/tauri", () => ({
  getDiff: vi.fn().mockResolvedValue({
    files: [],
    totalAdditions: 0,
    totalDeletions: 0,
  }),
  getFileDiff: vi.fn().mockResolvedValue({
    original: "",
    modified: "",
    language: "text",
  }),
  getRepoDiff: vi.fn().mockResolvedValue({
    files: [],
    totalAdditions: 0,
    totalDeletions: 0,
  }),
  getRepoFileDiff: vi.fn().mockResolvedValue({
    original: "",
    modified: "",
    language: "text",
  }),
  listen: vi.fn().mockResolvedValue(() => {}),
}));

import { DiffViewer } from "./DiffViewer";
import { useDiffStore } from "../../stores/diffStore";
import { useAgentStore } from "../../stores/agentStore";

const mockLoadDiff = vi.fn();
const mockRefresh = vi.fn();
const mockSelectFile = vi.fn();

beforeEach(() => {
  useDiffStore.setState({
    diffResults: {},
    selectedFile: {},
    fileDiffs: {},
    loading: {},
    error: {},
    loadDiff: mockLoadDiff,
    refresh: mockRefresh,
    selectFile: mockSelectFile,
  });
  useAgentStore.setState({ agents: {} });
  vi.clearAllMocks();
});

describe("DiffViewer", () => {
  it("shows Loading diff... when loading with no result", () => {
    useDiffStore.setState({ loading: { "ws-1": true } });
    render(<DiffViewer workspaceId="ws-1" />);
    expect(screen.getByText("Loading diff...")).toBeInTheDocument();
  });

  it("shows No changes when diffResult is null", () => {
    useDiffStore.setState({
      diffResults: { "ws-1": null },
      loading: {},
    });
    render(<DiffViewer workspaceId="ws-1" />);
    expect(screen.getByText("No changes")).toBeInTheDocument();
  });

  it("shows No changes when diffResult has empty files array", () => {
    useDiffStore.setState({
      diffResults: {
        "ws-1": { files: [], totalAdditions: 0, totalDeletions: 0 },
      },
      loading: {},
    });
    render(<DiffViewer workspaceId="ws-1" />);
    expect(screen.getByText("No changes")).toBeInTheDocument();
  });

  it("shows file count and stats in header", () => {
    useDiffStore.setState({
      diffResults: {
        "ws-1": {
          files: [
            {
              path: "src/app.ts",
              status: "Modified",
              additions: 10,
              deletions: 0,
            },
            {
              path: "src/new.ts",
              status: "Added",
              additions: 20,
              deletions: 0,
            },
          ],
          totalAdditions: 30,
          totalDeletions: 7,
        },
      },
    });
    render(<DiffViewer workspaceId="ws-1" />);
    expect(screen.getByText("2 files changed")).toBeInTheDocument();
    expect(screen.getByText("+30")).toBeInTheDocument();
    expect(screen.getByText("-7")).toBeInTheDocument();
  });

  it("shows Refresh button", () => {
    useDiffStore.setState({
      diffResults: {
        "ws-1": {
          files: [
            {
              path: "src/app.ts",
              status: "Modified",
              additions: 1,
              deletions: 0,
            },
          ],
          totalAdditions: 1,
          totalDeletions: 0,
        },
      },
    });
    render(<DiffViewer workspaceId="ws-1" />);
    expect(screen.getByText("Refresh")).toBeInTheDocument();
  });

  it("clicking Refresh calls refresh", () => {
    useDiffStore.setState({
      diffResults: {
        "ws-1": {
          files: [
            {
              path: "src/app.ts",
              status: "Modified",
              additions: 1,
              deletions: 0,
            },
          ],
          totalAdditions: 1,
