      diffResults: {
        "ws-1": {
          files: [
            {
              path: "src/app.ts",
              status: "Modified",
              additions: 1,
              deletions: 0,
            },
          ],
          totalAdditions: 1,
          totalDeletions: 0,
        },
      },
    });
    render(<DiffViewer workspaceId="ws-1" />);
    fireEvent.click(screen.getByText("src/app.ts"));
    expect(mockSelectFile).toHaveBeenCalledWith("ws-1", "src/app.ts");
